class PerformanceSnapshot { final double fps, averageFrameMs, worstFrameMs; final int samples, activeComponents; const PerformanceSnapshot({required this.fps,required this.averageFrameMs,required this.worstFrameMs,required this.samples,required this.activeComponents}); }
class PerformanceMonitor { final List<double> _frames=<double>[]; int _activeComponents=0; void recordFrame(double dt,{required int activeComponents}){if(dt<=0||dt.isNaN||dt.isInfinite)return;_frames.add(dt);if(_frames.length>120)_frames.removeAt(0);_activeComponents=activeComponents;} PerformanceSnapshot get snapshot{if(_frames.isEmpty)return const PerformanceSnapshot(fps:0,averageFrameMs:0,worstFrameMs:0,samples:0,activeComponents:0);final total=_frames.fold<double>(0,(a,b)=>a+b);final worst=_frames.reduce((a,b)=>a>b?a:b);final avg=total/_frames.length;return PerformanceSnapshot(fps:avg>0?1/avg:0,averageFrameMs:avg*1000,worstFrameMs:worst*1000,samples:_frames.length,activeComponents:_activeComponents);} }
